import ee, sys, math
ee.Initialize(project='earthsense-436113')

# 1) Geometry
def get_indonesia_geom():
    try:
        lsib = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
        indo_fc = lsib.filter(ee.Filter.Or(
            ee.Filter.eq('country_na', 'Indonesia'),
            ee.Filter.eq('country_co', 'IDN')
        ))
        return ee.Geometry(indo_fc.geometry())
    except Exception as e:
        print(f"Dataset load error: {str(e)[:120]}")
        print("D")
        sys.exit(0)

indo = get_indonesia_geom()
sumatra_rect = ee.Geometry.Rectangle([94.5, -6.6, 106.2, 6.6], geodesic=False)
borneo_rect  = ee.Geometry.Rectangle([108.0, -4.9, 119.8, 7.8], geodesic=False)
sumatra = sumatra_rect.intersection(indo, maxError=1)
borneo  = borneo_rect.intersection(indo, maxError=1)

dates = {
    '2022': ('2022-01-01', '2022-12-31'),
    '2023': ('2023-01-01', '2023-12-31'),
}

# 2) Counting detections using MODIS Fire Locations (Terra+Aqua combined)
def count_detections(geom, start, end, conf_min=60):
    try:
        fc = (ee.FeatureCollection('MODIS/061/MCD14DL')
              .filterBounds(geom)
              .filterDate(start, end))
        if conf_min is not None:
            fc = fc.filter(ee.Filter.gte('confidence', conf_min))
        return int(fc.size().getInfo())
    except Exception as e:
        msg = str(e)
        if ('not found' in msg.lower()) or ('invalid' in msg.lower()):
            print(f"Dataset error: {msg[:120]}")
            print("D")
            sys.exit(0)
        print(f"Calculation failure: {msg[:120]}")
        print("C3")
        sys.exit(0)

# 3) Compute counts per island and totals; treat zero as valid
counts = {}
for yr, (s, e) in dates.items():
    s_cnt = count_detections(sumatra, s, e, conf_min=60)
    b_cnt = count_detections(borneo,  s, e, conf_min=60)
    counts[(yr, 'sumatra')] = s_cnt
    counts[(yr, 'borneo')]  = b_cnt
    counts[(yr, 'total')]   = s_cnt + b_cnt

# 4) Evidence prints (<=20 lines)
print("Dataset: MODIS/061/MCD14DL (MODIS Fire Locations, confidence>=60)")
print("Region: Sumatra ∪ Borneo clipped to Indonesia")
for yr in ['2022', '2023']:
    print(f"{yr} Detections - Sumatra: {counts[(yr,'sumatra')]}, Borneo: {counts[(yr,'borneo')]}, Total: {counts[(yr,'total')]}")

diff = counts[('2023','total')] - counts[('2022','total')]
pct = (diff / counts[('2022','total')] * 100.0) if counts[('2022','total')] > 0 else float('nan')
pct_str = "NaN" if math.isnan(pct) else f"{pct:.1f}%"
print(f"Change 2023 vs 2022: {diff} detections ({pct_str})")

# 5) Final Answer Tag
if math.isnan(pct):  # 2022 total == 0; decide increase purely by absolute diff
    if counts[('2023','total')] > counts[('2022','total')]:
        print("A")
    else:
        print("B")
else:
    if counts[('2023','total')] > counts[('2022','total')]:
        print("A")
    else:
        print("B")
